def transform(grid):
    # Hollow square frames are filled according to their interior size:
    # 4x4 interiors become 2, 3x3 interiors and single-cell holes become 7.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            ih, iw = y1 - y0 - 1, x1 - x0 - 1
            if ih <= 0 or iw <= 0:
                continue
            fill = 2 if (ih, iw) == (4, 4) or (ih, iw) == (2, 2) else 7
            for y in range(y0 + 1, y1):
                for x in range(x0 + 1, x1):
                    if grid[y][x] == bg:
                        out[y][x] = fill
    return out

